extra_css:
/* Cloud Forest surfaces: wet basalt slabs rimmed with a specular dewdrop edge and bioluminescent lichen glint;
   hover catches a shaft of dawn sun across the wet leaf-vein border. Headings gleam like sunlit dew on jade.
   Scoped to own surfaces only. */
html[data-atmo="canopy"] .card, html[data-atmo="canopy"] .panel, html[data-atmo="canopy"] .gx-card {
  background: radial-gradient(120% 85% at 30% 0%, rgba(166,226,122,.08), transparent 62%), linear-gradient(180deg, rgba(20,38,29,.88), rgba(6,13,9,.94));
  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  box-shadow: inset 0 1px 0 rgba(210,244,184,.28), inset 0 0 0 1px rgba(166,226,122,.22), 0 18px 46px rgba(0,0,0,.76);
  transition: box-shadow .4s ease, transform .5s cubic-bezier(.2,1,.3,1), background .6s ease; }
html[data-atmo="canopy"] .card:hover, html[data-atmo="canopy"] .gx-card:hover {
  transform: translateY(-2px);
  background: radial-gradient(120% 85% at 30% 0%, rgba(190,245,148,.14), transparent 65%), linear-gradient(180deg, rgba(24,46,35,.91), rgba(8,17,12,.95));
  box-shadow: inset 0 1px 0 rgba(225,252,204,.48), inset 0 0 0 1px rgba(166,226,122,.46), 0 0 28px rgba(166,226,122,.12), 0 22px 54px rgba(0,0,0,.8); }
html[data-atmo="canopy"] h1, html[data-atmo="canopy"] h2 { background: linear-gradient(180deg, #f4fff7, #bfe8cb 52%, #7bb892); -webkit-background-clip: text; background-clip: text; color: transparent; }
html[data-atmo="canopy"] h1 { filter: drop-shadow(0 2px 14px rgba(0,0,0,.9)) drop-shadow(0 0 2px rgba(0,0,0,.85)); }

